void saveSettings(){WritePrivateProfileStringW(L"Overlay",L"Opacity",std::to_wstring(static_cast<int>(g_appearance.opacity*100)).c_str(),g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"Accent",std::to_wstring(g_appearance.accentRgb).c_str(),g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"Compact",g_appearance.compact?L"1":L"0",g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"ArtworkBackground",g_appearance.artworkBackground?L"1":L"0",g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"DynamicAccent",g_appearance.dynamicAccent?L"1":L"0",g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"Overkill",g_appearance.overkill?L"1":L"0",g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"Corner",std::to_wstring(g_appearance.corner).c_str(),g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"ShowBanner",g_appearance.showBanner?L"1":L"0",g_settingsPath.c_str());WritePrivateProfileStringW(L"Overlay",L"Backend",std::to_wstring(g_backend).c_str(),g_settingsPath.c_str());std::wstring keys;for(size_t i=0;i<g_combo.size();++i){if(i)keys+=L",";keys+=std::to_wstring(g_combo[i]);}WritePrivateProfileStringW(L"Overlay",L"Shortcut",keys.c_str(),g_settingsPath.c_str());}
void loadSettings(){wchar_t local[MAX_PATH]{};GetEnvironmentVariableW(L"LOCALAPPDATA",local,MAX_PATH);std::wstring dir=std::wstring(local)+L"\\NihonsMusicFramework";CreateDirectoryW(dir.c_str(),nullptr);g_settingsPath=dir+L"\\settings.ini";if(GetFileAttributesW(g_settingsPath.c_str())==INVALID_FILE_ATTRIBUTES){TASKDIALOG_BUTTON buttons[]={{9,L"DirectX 9"},{10,L"DirectX 10"},{11,L"DirectX 11 (recommended)"},{12,L"DirectX 12"}};TASKDIALOGCONFIG c{};c.cbSize=sizeof(c);c.dwFlags=TDF_USE_COMMAND_LINKS;c.pszWindowTitle=L"Nihon's Music Framework";c.pszMainInstruction=L"Choose a renderer";c.pszContent=L"You can change this later. A renderer change takes effect after restart.";c.pButtons=buttons;c.cButtons=4;c.nDefaultButton=11;int selected=11;TaskDialogIndirect(&c,&selected,nullptr,nullptr);g_backend=selected;saveSettings();}g_appearance.opacity=std::clamp(GetPrivateProfileIntW(L"Overlay",L"Opacity",92,g_settingsPath.c_str())/100.f,.1f,1.f);g_appearance.accentRgb=GetPrivateProfileIntW(L"Overlay",L"Accent",0x68D5C8,g_settingsPath.c_str());g_appearance.compact=GetPrivateProfileIntW(L"Overlay",L"Compact",0,g_settingsPath.c_str())!=0;g_appearance.artworkBackground=GetPrivateProfileIntW(L"Overlay",L"ArtworkBackground",0,g_settingsPath.c_str())!=0;g_appearance.dynamicAccent=GetPrivateProfileIntW(L"Overlay",L"DynamicAccent",0,g_settingsPath.c_str())!=0;g_appearance.overkill=GetPrivateProfileIntW(L"Overlay",L"Overkill",0,g_settingsPath.c_str())!=0;g_appearance.showBanner=GetPrivateProfileIntW(L"Overlay",L"ShowBanner",1,g_settingsPath.c_str())!=0;g_appearance.corner=static_cast<std::uint32_t>(std::clamp<int>(static_cast<int>(GetPrivateProfileIntW(L"Overlay",L"Corner",1,g_settingsPath.c_str())),0,3));g_backend=GetPrivateProfileIntW(L"Overlay",L"Backend",11,g_settingsPath.c_str());wchar_t keys[256]{};GetPrivateProfileStringW(L"Overlay",L"Shortcut",L"16",keys,256,g_settingsPath.c_str());g_combo.clear();wchar_t* p=keys;while(*p){wchar_t* end{};long value=wcstol(p,&end,10);if(end==p)break;if(value>0&&value<256)g_combo.push_back(static_cast<int>(value));p=(*end==L',')?end+1:end;}if(g_combo.empty())g_combo={VK_SHIFT};updateComboName();}
