bool handleTraySetting(HWND hwnd,UINT command){if(command>kMenuOpacityBase&&command<=kMenuOpacityBase+100){g_appearance.opacity=float(command-kMenuOpacityBase)/100.f;applyOpacity(hwnd);}else if(command>=kMenuCornerBase&&command<kMenuCornerBase+4){g_appearance.corner=command-kMenuCornerBase;updateCornerName();if(g_appearance.overkill&&!g_appearance.settingsOpen)positionOverkill(hwnd);}else if(command>=kMenuBackendBase+9&&command<=kMenuBackendBase+12){g_backend=static_cast<int>(command-kMenuBackendBase);updateBackendName();}else switch(command){case kMenuCompact:g_appearance.compact=!g_appearance.compact;resizeWindow(hwnd);break;case kMenuDynamicAccent:g_appearance.dynamicAccent=!g_appearance.dynamicAccent;break;case kMenuArtworkBackground:g_appearance.artworkBackground=!g_appearance.artworkBackground;break;case kMenuOverkill:g_appearance.overkill=!g_appearance.overkill;resizeWindow(hwnd);break;case kMenuBanner:g_appearance.showBanner=!g_appearance.showBanner;break;case kMenuAccent:{CHOOSECOLORW cc{sizeof(cc)};static COLORREF custom[16]{};cc.hwndOwner=hwnd;cc.rgbResult=RGB((g_appearance.accentRgb>>16)&255,(g_appearance.accentRgb>>8)&255,g_appearance.accentRgb&255);cc.lpCustColors=custom;cc.Flags=CC_FULLOPEN|CC_RGBINIT;if(ChooseColorW(&cc))g_appearance.accentRgb=(GetRValue(cc.rgbResult)<<16)|(GetGValue(cc.rgbResult)<<8)|GetBValue(cc.rgbResult);break;}case kMenuShortcut:openSettings(hwnd);g_recording=true;g_recorded.clear();ZeroMemory(g_scanWasDown,sizeof(g_scanWasDown));updateComboName();break;default:return false;}saveSettings();InvalidateRect(hwnd,nullptr,FALSE);return true;}
void rebuild(HWND hwnd,UINT w,UINT h){if(!g_swap||!w||!h)return;g_context->ClearState();g_overlay.reset();if(SUCCEEDED(g_swap->ResizeBuffers(0,w,h,DXGI_FORMAT_UNKNOWN,0))){g_overlay=std::make_unique<mo::IntegrationContext>(mo::Backend::D3D11);g_overlay->initialize({hwnd,g_device.Get(),g_swap.Get(),nullptr});}}
void scanRecording(){bool any=false;for(int vk=8;vk<255;++vk){if(vk==VK_LBUTTON||vk==VK_RBUTTON||vk==VK_MBUTTON)continue;bool down=(GetAsyncKeyState(vk)&0x8000)!=0;if(down&&!g_scanWasDown[vk]&&std::find(g_recorded.begin(),g_recorded.end(),vk)==g_recorded.end())g_recorded.push_back(vk);g_scanWasDown[vk]=down;if(down)any=true;}if(!any&&!g_recorded.empty()){g_combo=g_recorded;g_recorded.clear();g_recording=false;updateComboName();saveSettings();}}
void scanToggle(HWND hwnd){bool down=comboDown();if(down&&!g_comboWasDown){ULONGLONG now=GetTickCount64();if(g_lastTap&&now-g_lastTap<=1000){g_interactive=!g_interactive;g_lastTap=0;if(!g_interactive&&g_appearance.settingsOpen)transitionSettings(hwnd,false);applyInteraction(hwnd);}else g_lastTap=now;}g_comboWasDown=down;if(g_lastTap&&GetTickCount64()-g_lastTap>1000)g_lastTap=0;}

